pub fn simple_nested(a: &mut Vec<i32>, b: &Vec<i32>, N: i32) -> i32 {
    // Assumptions from the problem statement:
    // - N is non-negative and N <= 0x3FFF_FFFF
    // - a.len() == b.len() == N
    // - for each i in [0, N), b[i] is either i or i+1

    let n = N as usize;

    debug_assert!(N >= 0);
    debug_assert!(a.len() == n);
    debug_assert!(b.len() == n);

    let mut sum: i32 = 0;

    for i in 0..n {
        let ii = i as i32;
        let bi = b[i];

        debug_assert!(bi == ii || bi == ii + 1);

        let v = if bi == ii { 1 } else { 2 };
        a[i] = v;
        sum += v;
    }

    sum
}